-- Core Banking Prototype 0.3.79 Fix87
-- CIF Religion / Religious Denomination reference data
-- Idempotent migration for existing Oracle CIF schemas.

SET DEFINE OFF;
SET SERVEROUTPUT ON;

DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM ALL_TABLES WHERE OWNER='CIF' AND TABLE_NAME='REF_RELIGION';
  IF v_count = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE CIF.REF_RELIGION (
        RELIGION_CODE VARCHAR2(50 CHAR) NOT NULL,
        NAME_FA VARCHAR2(200 CHAR) NOT NULL,
        NAME_EN VARCHAR2(200 CHAR),
        DESCRIPTION_FA VARCHAR2(1000 CHAR),
        SORT_ORDER NUMBER(10) DEFAULT 10 NOT NULL,
        IS_ACTIVE NUMBER(1) DEFAULT 1 NOT NULL,
        PARENT_CODE VARCHAR2(50 CHAR),
        VALID_FROM DATE,
        VALID_TO DATE,
        RECORD_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
        CONSTRAINT PK_REF_RELIGION PRIMARY KEY (RELIGION_CODE) USING INDEX TABLESPACE ITS_CIF,
        CONSTRAINT CK_REF_RELIGION_01 CHECK (IS_ACTIVE IN (0,1)),
        CONSTRAINT CK_REF_RELIGION_02 CHECK (VALID_TO IS NULL OR VALID_FROM IS NULL OR VALID_TO >= VALID_FROM),
        CONSTRAINT CK_REF_RELIGION_03 CHECK (SORT_ORDER >= 0),
        CONSTRAINT CK_REF_RELIGION_04 CHECK (RECORD_VERSION >= 1)
      ) TABLESPACE TS_CIF
    ]';
  END IF;
END;
/

DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM ALL_TABLES WHERE OWNER='CIF' AND TABLE_NAME='REF_RELIGIOUS_DENOMINATION';
  IF v_count = 0 THEN
    EXECUTE IMMEDIATE q'[
      CREATE TABLE CIF.REF_RELIGIOUS_DENOMINATION (
        DENOMINATION_CODE VARCHAR2(50 CHAR) NOT NULL,
        RELIGION_CODE VARCHAR2(50 CHAR) NOT NULL,
        NAME_FA VARCHAR2(200 CHAR) NOT NULL,
        NAME_EN VARCHAR2(200 CHAR),
        DESCRIPTION_FA VARCHAR2(1000 CHAR),
        SORT_ORDER NUMBER(10) DEFAULT 10 NOT NULL,
        IS_ACTIVE NUMBER(1) DEFAULT 1 NOT NULL,
        PARENT_CODE VARCHAR2(50 CHAR),
        VALID_FROM DATE,
        VALID_TO DATE,
        RECORD_VERSION NUMBER(10) DEFAULT 1 NOT NULL,
        CONSTRAINT PK_REF_REL_DENOM PRIMARY KEY (DENOMINATION_CODE) USING INDEX TABLESPACE ITS_CIF,
        CONSTRAINT CK_REF_REL_DENOM_01 CHECK (IS_ACTIVE IN (0,1)),
        CONSTRAINT CK_REF_REL_DENOM_02 CHECK (VALID_TO IS NULL OR VALID_FROM IS NULL OR VALID_TO >= VALID_FROM),
        CONSTRAINT CK_REF_REL_DENOM_03 CHECK (SORT_ORDER >= 0),
        CONSTRAINT CK_REF_REL_DENOM_04 CHECK (RECORD_VERSION >= 1),
        CONSTRAINT FK_REF_REL_DENOM_RELIGION FOREIGN KEY (RELIGION_CODE) REFERENCES CIF.REF_RELIGION (RELIGION_CODE),
        CONSTRAINT FK_REF_REL_DENOM_PARENT FOREIGN KEY (PARENT_CODE) REFERENCES CIF.REF_RELIGIOUS_DENOMINATION (DENOMINATION_CODE)
      ) TABLESPACE TS_CIF
    ]';
  END IF;
END;
/

DECLARE
  v_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_count FROM ALL_INDEXES WHERE OWNER='CIF' AND INDEX_NAME='IX_REF_REL_DENOM_RELIGION';
  IF v_count = 0 THEN
    EXECUTE IMMEDIATE 'CREATE INDEX CIF.IX_REF_REL_DENOM_RELIGION ON CIF.REF_RELIGIOUS_DENOMINATION (RELIGION_CODE) TABLESPACE ITS_CIF';
  END IF;
END;
/

COMMENT ON TABLE CIF.REF_RELIGION IS 'اطلاعات پایه دین برای Party شخص حقیقی؛ داده حساس و مشمول کنترل دسترسی و حریم خصوصی';
COMMENT ON COLUMN CIF.REF_RELIGION.RELIGION_CODE IS 'کد دین';
COMMENT ON COLUMN CIF.REF_RELIGION.NAME_FA IS 'عنوان فارسی دین';
COMMENT ON COLUMN CIF.REF_RELIGION.NAME_EN IS 'عنوان انگلیسی دین';
COMMENT ON COLUMN CIF.REF_RELIGION.DESCRIPTION_FA IS 'توضیحات فارسی دین';
COMMENT ON COLUMN CIF.REF_RELIGION.SORT_ORDER IS 'ترتیب نمایش';
COMMENT ON COLUMN CIF.REF_RELIGION.IS_ACTIVE IS 'فعال بودن؛ 1 فعال و 0 غیرفعال';
COMMENT ON COLUMN CIF.REF_RELIGION.PARENT_CODE IS 'کد والد اختیاری دین';
COMMENT ON COLUMN CIF.REF_RELIGION.VALID_FROM IS 'شروع اعتبار';
COMMENT ON COLUMN CIF.REF_RELIGION.VALID_TO IS 'پایان اعتبار';
COMMENT ON COLUMN CIF.REF_RELIGION.RECORD_VERSION IS 'نسخه رکورد';

COMMENT ON TABLE CIF.REF_RELIGIOUS_DENOMINATION IS 'اطلاعات پایه مذهب یا شاخه دینی وابسته به دین';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.DENOMINATION_CODE IS 'کد مذهب یا شاخه دینی';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.RELIGION_CODE IS 'کد دین والد';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.NAME_FA IS 'عنوان فارسی مذهب';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.NAME_EN IS 'عنوان انگلیسی مذهب';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.DESCRIPTION_FA IS 'توضیحات فارسی مذهب';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.SORT_ORDER IS 'ترتیب نمایش';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.IS_ACTIVE IS 'فعال بودن؛ 1 فعال و 0 غیرفعال';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.PARENT_CODE IS 'کد مذهب والد در ساختار سلسله‌مراتبی';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.VALID_FROM IS 'شروع اعتبار';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.VALID_TO IS 'پایان اعتبار';
COMMENT ON COLUMN CIF.REF_RELIGIOUS_DENOMINATION.RECORD_VERSION IS 'نسخه رکورد';

