MERGE INTO CIF.REF_RELIGION T
USING (SELECT 'ISLAM' AS CODE, 'اسلام' AS FA, 'Islam' AS EN, 'دین اسلام.' AS DESCR, 10 AS ORD, 1 AS ACTIVE, NULL AS PARENT_CODE, NULL AS VALID_FROM, NULL AS VALID_TO, 1 AS RECORD_VERSION FROM DUAL) S
ON (T.RELIGION_CODE=S.CODE)
WHEN MATCHED THEN UPDATE SET T.NAME_FA=S.FA, T.NAME_EN=S.EN, T.DESCRIPTION_FA=S.DESCR, T.SORT_ORDER=S.ORD, T.IS_ACTIVE=S.ACTIVE, T.PARENT_CODE=S.PARENT_CODE, T.VALID_FROM=S.VALID_FROM, T.VALID_TO=S.VALID_TO, T.RECORD_VERSION=S.RECORD_VERSION
